package com.forgeci.domain.organization;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="organizations",schema="forgeci",uniqueConstraints=@UniqueConstraint(name="uk_org_slug",columnNames="slug"))
public class Organization { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(nullable=false,length=120) private String name; @Column(nullable=false,length=80) private String slug; @Column(name="created_at",nullable=false,updatable=false) private Instant createdAt; @Column(name="updated_at",nullable=false) private Instant updatedAt; protected Organization(){} public Organization(String name,String slug){this.name=name;this.slug=slug;} @PrePersist void create(){var n=Instant.now();createdAt=n;updatedAt=n;} @PreUpdate void update(){updatedAt=Instant.now();} public UUID getId(){return id;} public String getName(){return name;} public String getSlug(){return slug;} public Instant getCreatedAt(){return createdAt;} public Instant getUpdatedAt(){return updatedAt;} }
